// Resolve a requirement's named declaration to the module that declares it
// (rust/src/agentic_coding/requirement_resolution.rs). The census comes from
// `crate/self_ast_census.mjs` `workspace()`.

import { moduleSymbol, modulesDeclaring, workspace } from './crate/self_ast_census.mjs';
import { isAlphanumeric } from './write_str.mjs';
import { hasHost, readText } from './host.mjs';
import { meaningFiles, parseLexiconText, words as meaningWords } from './crate/seed_meanings.mjs';

/** Mirrors `fn resolve_requirement_target`: `{module_path, symbol, kind}` or null. */
export function resolveRequirementTarget(requirement) {
  return resolveIn(workspace(), requirement);
}

/** Mirrors `fn resolve_in`. */
export function resolveIn(census, requirement) {
  const tokens = tokensOf(requirement);
  for (const token of tokens) {
    if (!looksLikeDeclaredName(token)) continue;
    const named = modulesDeclaring(census, token)
      .map((module) => [module, moduleSymbol(module, token)])
      .filter(([, symbol]) => symbol !== null);
    if (named.length) return unique(named, tokens);
  }
  const words = tokens.map((token) => singular(token.toLowerCase()));
  let best = [];
  let bestLength = 0;
  for (const module of census.modules) {
    for (const symbol of module.symbols) {
      if (symbol.kind !== 'const' && symbol.kind !== 'static') continue;
      const parts = symbol.name.split('_').filter((part) => part !== '').map((part) => singular(part.toLowerCase()));
      if (parts.length < 2 || !parts.every((part) => words.includes(part))) continue;
      if (parts.length > bestLength) {
        bestLength = parts.length;
        best = [[module, symbol]];
      } else if (parts.length === bestLength) best.push([module, symbol]);
    }
  }
  return best.length ? unique(best, tokens) : hasHost()
    ? resolveSeedTarget(census, requirement, meaningFiles().map((path) => [path, readText(path)])) : null;
}

/** Bind a concrete canonical surface and role to its actually declared registry constant.
 * The constant spelling follows the seed registry generator; no seed or prompt is privileged.
 * Equal evidence for different targets is unresolved. */
export function resolveSeedTarget(census, requirement, sources) {
  const tokens = tokensOf(requirement).map((token) => token.toLowerCase());
  const roleWords = tokens.map(singular);
  let bestLength = 0;
  const best = new Map();
  for (const [path, source] of sources) {
    const stem = path.split('/').at(-1)?.replace(/\.lino$/u, '');
    if (!path.endsWith('.lino') || !/^[A-Za-z0-9_-]+$/u.test(stem)) continue;
    const name = stem.toUpperCase().replaceAll('-', '_') + '_LINO';
    const candidates = modulesDeclaring(census, name).map((module) => [module, moduleSymbol(module, name)])
      .filter(([, symbol]) => symbol.kind === 'const' || symbol.kind === 'static');
    if (!candidates.length) continue;
    for (const meaning of parseLexiconText(source)) {
      if (!meaning.roles.some((role) => role.split(/[_-]/u).some((part) => roleWords.includes(singular(part.toLowerCase()))))) continue;
      for (const surface of meaningWords(meaning)) {
        if (surface.includes('…')) continue;
        const parts = tokensOf(surface).map((token) => token.toLowerCase());
        if (!parts.length || !tokens.some((_, at) => parts.every((part, offset) => tokens[at + offset] === part))) continue;
        if (parts.length > bestLength) { bestLength = parts.length; best.clear(); }
        if (parts.length === bestLength) for (const [module, symbol] of candidates) best.set(module.path + ':' + symbol.name, target(module, symbol));
      }
    }
  }
  return best.size === 1 ? best.values().next().value : null;
}

function unique(candidates, tokens) {
  if (candidates.length === 1) return target(...candidates[0]);
  const words = tokens.map((token) => singular(token.toLowerCase()));
  const scored = candidates.map(([module, symbol]) => [
    pathWords(module.path).filter((word) => words.includes(word)).length, module, symbol,
  ]);
  if (!scored.length) return null;
  const top = Math.max(...scored.map(([score]) => score));
  const winners = scored.filter(([score]) => score === top);
  return winners.length === 1 ? target(winners[0][1], winners[0][2]) : null;
}

function target(module, symbol) {
  return { module_path: module.path, symbol: symbol.name, kind: symbol.kind };
}

function pathWords(path) {
  return path.split(/[/_.]/u)
    .filter((part) => part !== '' && part !== 'src' && part !== 'rs' && part !== 'mod')
    .map((part) => singular(part.toLowerCase()));
}

function tokensOf(text) {
  const out = [];
  let current = '';
  for (const character of text) {
    if (isAlphanumeric(character) || character === '_') current += character;
    else {
      if (current) out.push(current);
      current = '';
    }
  }
  if (current) out.push(current);
  return out;
}

function looksLikeDeclaredName(token) {
  return token.length >= 2 && /[A-Z]/.test(token) && /^[A-Z0-9_]+$/.test(token);
}

function singular(word) {
  return new TextEncoder().encode(word).length > 3 && word.endsWith('s') && !word.endsWith('ss') ? word.slice(0, -1) : word;
}

//! Resolve a requirement that names behaviour or a declaration, not a file
//! (issue #1085 D2.2).
//!
//! The self-AST census is the links network over the workspace's own source.
//! A requirement such as "add wikiquote as a web search provider" is resolved
//! by querying it for the `const` or `static` whose identifier words the
//! requirement contains, or for the identifier the requirement names, so the
//! prompt never has to name `src/web_search_core.rs`.

use std::cmp::Ordering;

use crate::self_ast_census::{ModuleCensus, SymbolSpan, WorkspaceCensus, workspace};

/// Where a requirement lands: the module and the declaration it changes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RequirementTarget {
    pub module_path: String,
    pub symbol: String,
    pub kind: String,
}

/// Resolve `requirement` against the live workspace census.
#[must_use]
pub fn resolve_requirement_target(requirement: &str) -> Option<RequirementTarget> {
    resolve_in(workspace(), requirement)
}

/// Resolve `requirement` against `census`.
///
/// An identifier the requirement names verbatim wins; otherwise the `const` or
/// `static` whose identifier words (singularised) all occur in the requirement
/// wins, longest identifier first. A tie between modules is broken by the
/// module path words the requirement mentions; a remaining tie is ambiguity and
/// resolves to nothing rather than to a guess. When identifier words do not bind,
/// an actual canonical seed surface and its semantic role can bind its declared owner.
#[must_use]
pub fn resolve_in(census: &WorkspaceCensus, requirement: &str) -> Option<RequirementTarget> {
    let tokens = tokens_of(requirement);
    for token in &tokens {
        if !looks_like_declared_name(token) {
            continue;
        }
        let named: Vec<(&ModuleCensus, &SymbolSpan)> = census
            .modules_declaring(token)
            .into_iter()
            .filter_map(|module| module.symbol(token).map(|symbol| (module, symbol)))
            .collect();
        if !named.is_empty() {
            return unique(&named, &tokens);
        }
    }

    let words: Vec<String> = tokens
        .iter()
        .map(|token| singular(&token.to_lowercase()))
        .collect();
    let mut best: Vec<(&ModuleCensus, &SymbolSpan)> = Vec::new();
    let mut best_length = 0;
    for module in &census.modules {
        for symbol in &module.symbols {
            if symbol.kind != "const" && symbol.kind != "static" {
                continue;
            }
            let parts: Vec<String> = symbol
                .name
                .split('_')
                .filter(|part| !part.is_empty())
                .map(|part| singular(&part.to_lowercase()))
                .collect();
            if parts.len() < 2 || !parts.iter().all(|part| words.contains(part)) {
                continue;
            }
            match parts.len().cmp(&best_length) {
                Ordering::Greater => {
                    best_length = parts.len();
                    best = vec![(module, symbol)];
                }
                Ordering::Equal => best.push((module, symbol)),
                Ordering::Less => {}
            }
        }
    }
    if best.is_empty() {
        let sources: Vec<_> = crate::seed::seed_files()
            .into_iter()
            .filter(|(_, text)| crate::seed::MEANING_FILES.contains(text))
            .collect();
        return resolve_seed_target(census, requirement, &sources);
    }
    unique(&best, &tokens)
}

/// Bind a concrete canonical surface and semantic role to a declared seed constant.
/// Constant spelling follows the seed registry generator. No seed is privileged;
/// equally supported distinct targets remain unresolved.
#[must_use]
pub fn resolve_seed_target(
    census: &WorkspaceCensus,
    requirement: &str,
    sources: &[(&str, &str)],
) -> Option<RequirementTarget> {
    let tokens: Vec<_> = tokens_of(requirement)
        .into_iter()
        .map(|word| word.to_lowercase())
        .collect();
    let role_words: Vec<_> = tokens.iter().map(|word| singular(word)).collect();
    let mut best_length = 0;
    let mut best: Vec<RequirementTarget> = Vec::new();
    for (path, source) in sources {
        let Some(stem) = path
            .rsplit('/')
            .next()
            .and_then(|name| name.strip_suffix(".lino"))
        else {
            continue;
        };
        if stem.is_empty()
            || !stem.chars().all(|character| {
                character.is_ascii_alphanumeric() || matches!(character, '_' | '-')
            })
        {
            continue;
        }
        let name = format!("{}_LINO", stem.to_ascii_uppercase().replace('-', "_"));
        let candidates: Vec<_> = census
            .modules_declaring(&name)
            .into_iter()
            .filter_map(|module| module.symbol(&name).map(|symbol| (module, symbol)))
            .filter(|(_, symbol)| matches!(symbol.kind.as_str(), "const" | "static"))
            .collect();
        if candidates.is_empty() {
            continue;
        }
        for meaning in crate::seed::parse_lexicon_text(source).meanings {
            if !meaning.roles.iter().any(|role| {
                role.split(['_', '-'])
                    .any(|part| role_words.contains(&singular(&part.to_lowercase())))
            }) {
                continue;
            }
            for surface in meaning.words() {
                if surface.contains('…') {
                    continue;
                }
                let parts: Vec<_> = tokens_of(surface)
                    .into_iter()
                    .map(|word| word.to_lowercase())
                    .collect();
                if parts.is_empty() || !tokens.windows(parts.len()).any(|window| window == parts) {
                    continue;
                }
                if parts.len() > best_length {
                    best_length = parts.len();
                    best.clear();
                }
                if parts.len() == best_length {
                    for (module, symbol) in &candidates {
                        let candidate = target(module, symbol);
                        if !best.contains(&candidate) {
                            best.push(candidate);
                        }
                    }
                }
            }
        }
    }
    if best.len() == 1 { best.pop() } else { None }
}

fn unique(
    candidates: &[(&ModuleCensus, &SymbolSpan)],
    tokens: &[String],
) -> Option<RequirementTarget> {
    if let [(module, symbol)] = candidates {
        return Some(target(module, symbol));
    }
    let words: Vec<String> = tokens
        .iter()
        .map(|token| singular(&token.to_lowercase()))
        .collect();
    let scored: Vec<(usize, &ModuleCensus, &SymbolSpan)> = candidates
        .iter()
        .map(|(module, symbol)| {
            let score = path_words(&module.path)
                .iter()
                .filter(|word| words.contains(word))
                .count();
            (score, *module, *symbol)
        })
        .collect();
    let top = scored.iter().map(|(score, _, _)| *score).max()?;
    let mut winners = scored
        .iter()
        .filter(|(score, _, _)| *score == top)
        .map(|(_, module, symbol)| (*module, *symbol));
    let (module, symbol) = winners.next()?;
    if winners.next().is_some() {
        return None;
    }
    Some(target(module, symbol))
}

fn target(module: &ModuleCensus, symbol: &SymbolSpan) -> RequirementTarget {
    RequirementTarget {
        module_path: module.path.clone(),
        symbol: symbol.name.clone(),
        kind: symbol.kind.clone(),
    }
}

fn path_words(path: &str) -> Vec<String> {
    path.split(['/', '_', '.'])
        .filter(|part| !part.is_empty() && *part != "src" && *part != "rs" && *part != "mod")
        .map(|part| singular(&part.to_lowercase()))
        .collect()
}

fn tokens_of(text: &str) -> Vec<String> {
    text.split(|character: char| !character.is_alphanumeric() && character != '_')
        .filter(|token| !token.is_empty())
        .map(str::to_owned)
        .collect()
}

fn looks_like_declared_name(token: &str) -> bool {
    token.len() >= 2
        && token
            .chars()
            .any(|character| character.is_ascii_uppercase())
        && token.chars().all(|character| {
            character.is_ascii_uppercase() || character.is_ascii_digit() || character == '_'
        })
}

fn singular(word: &str) -> String {
    if word.len() > 3 && word.ends_with('s') && !word.ends_with("ss") {
        word[..word.len() - 1].to_owned()
    } else {
        word.to_owned()
    }
}
